/**
 *
 * MenuSubmenuIndicator is a visual indicator that reflects whether the parent submenu is open or closed.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuSubmenuIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
import type { MenuSubmenuInstance } from './MenuSubmenu.types';
/**
 * Defines passthrough(pt) options type in MenuSubmenuIndicator component.
 */
export type MenuSubmenuIndicatorPassThroughType<E> = PassThroughType<MenuSubmenuIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of MenuSubmenuIndicator component.
 */
export interface MenuSubmenuIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuSubmenuIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in MenuSubmenuIndicator component.
 */
export interface MenuSubmenuIndicatorProps extends BaseComponentProps<MenuSubmenuIndicatorInstance, unknown, MenuSubmenuIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the open state of the parent submenu. Valid values are:
     * - "open": Indicator is visible when the submenu is expanded.
     * - "closed": Indicator is visible when the submenu is collapsed.
     */
    match?: 'open' | 'closed' | undefined;
}
/**
 * Defines valid state in MenuSubmenuIndicator component.
 */
export interface MenuSubmenuIndicatorState {
}
/**
 * Defines the methods and properties exposed by MenuSubmenuIndicator component.
 */
export interface MenuSubmenuIndicatorExposes {
    /**
     * The Menu component instance.
     */
    menu: MenuRootInstance | undefined | null;
    /**
     * The MenuSubmenu component instance.
     */
    submenu: MenuSubmenuInstance | undefined | null;
    /**
     * Whether the parent submenu is currently open.
     */
    open: boolean;
}
/**
 * Instance of MenuSubmenuIndicator component.
 */
export type MenuSubmenuIndicatorInstance = ComponentInstance<MenuSubmenuIndicatorProps, MenuSubmenuIndicatorState, MenuSubmenuIndicatorExposes>;
